"""固定 1280×720 基准的坐标换算工具。

所有 UI 布局常量都以 **1280×720 设计基准** 表达；实际截图/设备分辨率通过
:func:`scale_to` 换算。历史代码里散落的 ``/ 1920``、``/ 1080`` 运行时换算
改为在模块定义时用 :func:`capture_nx` / :func:`capture_ny` 一次性归一化，
这样同一常量在 1280×720、1920×1080 下指向同一屏幕位置。
"""

from __future__ import annotations

from typing import Final


BASE_WIDTH: Final = 1280
"""设计基准宽度（像素）。"""

BASE_HEIGHT: Final = 720
"""设计基准高度（像素）。"""

CAPTURE_WIDTH: Final = 1920
"""历史模板采集基准宽度（像素）；仅用于把旧常量换算到 1280×720 基准。"""

CAPTURE_HEIGHT: Final = 1080
"""历史模板采集基准高度（像素）。"""


def px(x: float, y: float) -> tuple[float, float]:
    """把 1280×720 基准像素点换算为 ``(x/W, y/H)`` 归一化坐标。"""
    return (x / BASE_WIDTH, y / BASE_HEIGHT)


def scale_to(width: float, height: float) -> tuple[float, float]:
    """返回 1280×720 基准到目标分辨率的 ``(sx, sy)`` 像素缩放因子。"""
    return (width / BASE_WIDTH, height / BASE_HEIGHT)


def capture_nx(x: float, *, capture_width: float = CAPTURE_WIDTH) -> float:
    """把采集基准像素 x 在定义期换算成归一化横向坐标。"""
    return x / capture_width


def capture_ny(y: float, *, capture_height: float = CAPTURE_HEIGHT) -> float:
    """把采集基准像素 y 在定义期换算成归一化纵向坐标。"""
    return y / capture_height


def capture_area(
    pixels: float,
    *,
    capture_width: float = CAPTURE_WIDTH,
    capture_height: float = CAPTURE_HEIGHT,
) -> float:
    """把采集基准下的像素面积换算成占整屏的比例（用于面积阈值）。"""
    return pixels / (capture_width * capture_height)


def to_pixels(
    point: tuple[float, float],
    width: float,
    height: float,
) -> tuple[float, float]:
    """把归一化坐标换算成目标分辨率下的像素坐标。"""
    return (point[0] * width, point[1] * height)
